def replace_params(path: str, param_convertors: dict[str, Convertor[typing.Any]], path_params: dict[str, str]) ->tuple[str, dict[str, str]]:
    remaining_params = path_params.copy()
    result = ""
    last_end = 0

    for match in PARAM_REGEX.finditer(path):
        param_name, convertor_type = match.groups("str")
        convertor_type = convertor_type.lstrip(":")

        if param_name in remaining_params:
            value = remaining_params.pop(param_name)
            convertor = param_convertors.get(param_name)
            if convertor:
                converted_value = convertor.convert(value)
                result += path[last_end:match.start()] + str(converted_value)
            else:
                result += path[last_end:match.start()] + str(value)
            last_end = match.end()

    result += path[last_end:]
    return result, remaining_params


def url_path_for(self, name: str, /, **path_params: typing.Any) ->URLPath:
    seen_params = set(path_params.keys())
    expected_params = set(self.param_convertors.keys())

    if name != self.name or seen_params != expected_params:
        raise NoMatchFound(name, path_params)

    path, remaining_params = replace_params(self.path_format, self.param_convertors, path_params)
    assert not remaining_params
    return URLPath(path=path, protocol="http")


